from contextlib import contextmanager
from robot.running.context import EXECUTION_CONTEXTS
import os.path
import datetime
from robot.libraries.BuiltIn import BuiltIn

LOGS_DIR_NAME = 'Logs'
DEFAULT_OUTPUT_DIR = os.path.abspath(os.path.curdir)
DEFAULT_EXEC_DIR = os.path.abspath(os.path.curdir)
DEFAULT_TEST_NAME = ''
DEFAULT_SUITE_NAME = ''
NO_SUBDIR = ''

builtin = BuiltIn()


def default_value_if_there_is_no_robot_context(default_value):
    def _check_robot_context(f):
        def wrapper(*args, **kwargs):
            try:
                return f(*args, **kwargs)
            except Exception:
                return default_value

        return wrapper

    return _check_robot_context


def unique_name(filename):
    return '{}_{}'.format(filename, datetime.datetime.now().strftime("%Y_%m_%dT%H_%M_%S_%f"))


def normalize(string):
    return string.replace(' ', '_')


def create_dir_if_needed(directory):
    if not os.path.exists(directory):
        os.system('mkdir -p {}'.format(directory))


@contextmanager
def change_dir(target_directory):
    initial_working_directory = os.getcwd()
    try:
        os.chdir(target_directory)
        yield
    finally:
        os.chdir(initial_working_directory)


@default_value_if_there_is_no_robot_context(DEFAULT_OUTPUT_DIR)
def get_robot_output_dir():
    return builtin.get_variable_value('${OUTPUT_DIR}')


@default_value_if_there_is_no_robot_context(DEFAULT_EXEC_DIR)
def get_robot_execution_dir():
    return builtin.get_variable_value('${EXECDIR}')


@default_value_if_there_is_no_robot_context(DEFAULT_SUITE_NAME)
def suite_name():
    return normalize(builtin.get_variable_value('${SUITE_NAME}'))


@default_value_if_there_is_no_robot_context(DEFAULT_TEST_NAME)
def test_name():
    return normalize(builtin.get_variable_value('${TEST_NAME}'))


def _prepare_directory(*args):
    logs_dir = normalize(os.path.join(get_robot_output_dir(), *args))
    create_dir_if_needed(logs_dir)
    return logs_dir


def base_logs_directory():
    return _prepare_directory(LOGS_DIR_NAME)


def logs_directory(dirname=NO_SUBDIR):
    if dirname:
        return _prepare_directory(LOGS_DIR_NAME, suite_name(), test_name(), dirname)
    return _prepare_directory(LOGS_DIR_NAME, suite_name(), test_name())


def is_robot_context_available():
    try:
        return EXECUTION_CONTEXTS.current is not None
    except Exception:
        return False


def unique_logs_filepath(name, extension):
    return os.path.join(logs_directory(), '{}.{}'.format(unique_name(name), extension))
